        "Orðið beygist ekki. Bitte schön er kurteislegra þegar eitthvað er boðið („gjörðu svo vel“), bitte sehr jafngilt afbrigði. Wie bitte? merkir „afsakið, hvað sagðirðu?“ ef maður heyrði ekki.",
