        "Der kemur líka fyrir í öðrum föllum: í kvenkyni í þágufalli og eignarfalli (der Frau) og með öllum nafnorðum í fleirtölu í eignarfalli (die Autos der Eltern). Í karlkyni er þolfallið den, þágufallið dem og eignarfallið des.",
        "Á íslensku er greinirinn viðskeyttur (maðurinn), en á þýsku stendur hann á undan og sýnir kyn og fall; kynið þarf að læra með orðinu."
