        "Myndir: du fährst, er fährt (a → ä), fuhr, ist gefahren. Ef ekkert beint andlag fylgir er notað sein: Ich bin nach Wien gefahren. Ef andlag í þolfalli fylgir (ekið bíl) er notað haben: Ich habe das Auto gefahren.",
        "Með spurningunni hvert? er sagt nach (borg, land), zu (manneskja, staður) eða in + þolfall; farartæki fá mit + þágufall. Íslenska „fara“ er skylt orð en á við alla hreyfingu, en fahren aðeins ferðir með farartæki."
