        "Myndir: ich habe, du hast, er hat, wir haben, ihr habt, sie haben; hatte, hat gehabt. Haben er líka hjálparsögn í núliðinni tíð: Ich habe das Buch gelesen — eins og íslenska „ég hef lesið bókina“.",
        "Í mörgum orðasamböndum lýsir haben ástandi: Hunger haben (vera svangur), Durst haben (vera þyrstur), Angst haben (vera hræddur), Recht haben (hafa rétt fyrir sér)."
