      "explanation": [
        "Meginhugmynd: kosten merkir „kosta“ — það verð sem vara eða þjónusta kostar: Das kostet fünf Euro — þetta kostar fimm evrur. Frumlagið er hluturinn, ekki manneskjan.",
        "Myndir: kostet, kostete, hat gekostet. Spurt um verð: Was kostet das? (Hvað kostar þetta?), Wie viel kostet der Pullover? Í fleirtölu: Die Schuhe kosten 60 Euro.",
        "Sá sem greiðir stendur í þolfalli: Das kostet mich zehn Euro — eins og á íslensku: þetta kostar mig tíu evrur. Í yfirfærðri merkingu getur kosten merkt að eitthvað tekur tíma eða fyrirhöfn: Das kostet viel Zeit."
      ],
      "examples": [
        {
          "de": "Das kostet fünf Euro.",
          "lv": "Þetta kostar fimm evrur."
        },
        {
          "de": "Was kostet das?",
          "lv": "Hvað kostar þetta?"
        },
        {
          "de": "Wie viel kostet der Pullover?",
          "lv": "Hvað kostar peysan?"
        },
        {
          "de": "Die Schuhe kosten sechzig Euro.",
          "lv": "Skórnir kosta sextíu evrur."
        },
        {
          "de": "Das kostet mich viel Zeit.",
          "lv": "Þetta kostar mig mikinn tíma."
        }
      ],
      "comparison": [
        {
          "word": "bezahlen",
          "meaning": "borga",
          "example": "Ich bezahle die Rechnung. – Ég borga reikninginn."
        },
        {
          "word": "zahlen",
          "meaning": "greiða, borga (manneskja)",
          "example": "Wir zahlen bar. – Við borgum með reiðufé."
        },
        {
          "word": "kaufen",
          "meaning": "kaupa",
          "example": "Ich kaufe ein Brot. – Ég kaupi brauð."
        }
      ],
      "tip": [
        "Kosten — verð hlutar, zahlen/bezahlen — manneskja borgar: Der Kaffee kostet drei Euro, ich bezahle ihn.",
        "Spurt um verð: Was kostet…? eða Wie viel kostet…?"
      ],
      "important": [
        "Nafnorðið die Kosten (aðeins í fleirtölu) merkir „kostnaður“; kosten sem sögn merkir „kosta“.",
        "Kosten getur líka merkt „smakka“ (Willst du die Suppe kosten?), en í daglegu tali er notað probieren."
      ],
