        "Stigbreyting: leiser (lægra), am leisesten. Á undan nafnorði fær það endingu: eine leise Stimme, leise Musik. Oft notað sem atviksorð: Die Kinder sprechen leise.",
        "Í yfirfærðri merkingu getur leise líka merkt „veikur, smávægilegur“: ein leiser Zweifel — smávægilegur efi."
