        "Fleirtala: die Männer (með hljóðvarpi). Eignarfall: des Mannes, þágufall fleirtölu: den Männern. Í samsettum orðum: Ehemann, Geschäftsmann (ft. Geschäftsleute).",
        "Munur á man: man (maður, almennt) er óákveðið fornafn, skrifað með litlum staf og einu n. Manneskja almennt heitir der Mensch."
