        "Algeng sambönd: morgen früh (í fyrramálið), morgen Abend (annað kvöld), bis morgen (sjáumst á morgun), übermorgen (hinn daginn). Hlutar dagsins á eftir morgen eru skrifaðir með stórum staf: morgen Nachmittag.",
        "Munur á Morgen: der Morgen er nafnorðið „morgunn“, en morgen er atviksorðið „á morgun“ — rétt eins og íslenska „á morgun“ er dregið af „morgunn“. Fremst í setningu greinir aðeins merkingin þau að."
