        "Orðaröð breytist ekki á eftir oder: Ich gehe nach Hause, oder ich bleibe hier. Í talmáli myndar oder aftast í setningu staðfestingarspurningu: Du kommst, oder? — Þú kemur, er það ekki?",
        "Föst samsetning: entweder … oder … — annaðhvort … eða …."
