        "Blaðsíðu er vísað til með auf Seite + tölu, án greinis: auf Seite 20. Þegar talað er um staðsetningu er notað auf der Seite (þgf.): auf der rechten Seite.",
        "Pappírsblað sem sérstakur hlutur heitir das Blatt, ekki die Seite — rétt eins og íslenska greinir á milli „blaðs“ og „blaðsíðu“."
