        "Á íslensku getur það verið ef (skilyrði: wenn du willst) eða þegar (endurtekning eða tímapunktur í framtíð: immer wenn, wenn ich Zeit habe). Ef aukasetningin stendur fyrst kemur sagnorð aðalsetningarinnar strax á eftir kommunni.",
