        "Máltíðir eru táknaðar með zu: zu Mittag essen (borða hádegismat), zu Abend essen (borða kvöldmat). Essen má líka nota án andlags: Wir essen um sieben.",
        "Ef dýr étur er notað fressen — eins og íslenska greinir á milli að borða og að éta; ef talað er um matinn sem nafnorð er skrifað das Essen."
